1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
3	import { corsHeaders, handlePreflight } from "../_shared/cors.ts";
4	
5	serve(async (req) => {
6	  const cors = corsHeaders(req);
7	
8	  const preflight = handlePreflight(req);
9	  if (preflight) return preflight;
10	
11	  try {
12	    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
13	    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
14	    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
15	
16	    const authHeader = req.headers.get("Authorization");
17	    if (!authHeader) throw new Error("No auth");
18	
19	    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
20	      global: { headers: { Authorization: authHeader } },
21	    });
22	    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
23	    if (userError || !user) throw new Error("Unauthorized");
24	    const userId = user.id;
25	
26	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
27	
28	    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
29	    if (!roles?.some((r: any) => r.role === "admin")) {
30	      return new Response(JSON.stringify({ error: "Admin access required" }), {
31	        status: 403, headers: { ...cors, "Content-Type": "application/json" },
32	      });
33	    }
34	
35	    const body = await req.json();
36	    const { key_name } = body;
37	
38	    // ─── DNS MX record check ───
39	    if (key_name === "DNS_MX_CHECK") {
40	      const domain = body.domain;
41	      if (!domain) throw new Error("Missing domain");
42	
43	      try {
44	        // Use Google DNS-over-HTTPS API to check MX records
45	        const dnsRes = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`);
46	        const dnsData = await dnsRes.json();
47	
48	        const mxRecords: { exchange: string; priority: number }[] = [];
49	        let pointsToExpected = false;
50	
51	        if (dnsData.Answer && Array.isArray(dnsData.Answer)) {
52	          for (const answer of dnsData.Answer) {
53	            if (answer.type === 15) { // MX record type
54	              const parts = answer.data.split(" ");
55	              const priority = parseInt(parts[0], 10);
56	              const exchange = (parts[1] || "").replace(/\.$/, "").toLowerCase();
57	              mxRecords.push({ exchange, priority });
58	              // Accept any valid MX record pointing to a known email provider
59	              if (exchange.includes("inbound.postmarkapp.com") || exchange.includes("resend") || exchange.includes("inbound-smtp") || exchange.includes("mx")) {
60	                pointsToExpected = true;
61	              }
62	            }
63	          }
64	        }
65	
66	        return new Response(JSON.stringify({
67	          status: mxRecords.length > 0 ? "success" : "no_records",
68	          domain,
69	          mx_records: mxRecords,
70	          points_to_expected: pointsToExpected,
71	        }), {
72	          headers: { ...cors, "Content-Type": "application/json" },
73	        });
74	      } catch (e: unknown) {
75	        return new Response(JSON.stringify({
76	          status: "error",
77	          error: e instanceof Error ? e.message : String(e),
78	        }), {
79	          headers: { ...cors, "Content-Type": "application/json" },
80	        });
81	      }
82	    }
83	
84	    if (!key_name) throw new Error("Missing key_name");
85	
86	    let status = "failed";
87	    let errorMsg = "";
88	    let details: Record<string, any> = {};
89	
90	    if (key_name === "OPENAI_API_KEY") {
91	      const openaiKey = Deno.env.get("OPENAI_API_KEY");
92	      if (!openaiKey) {
93	        errorMsg = "OPENAI_API_KEY secret is not configured";
94	      } else {
95	        try {
96	          const res = await fetch("https://api.openai.com/v1/models", {
97	            headers: { Authorization: `Bearer ${openaiKey}` },
98	          });
99	          if (res.ok) {
100	            status = "success";
101	          } else {
102	            const body = await res.text();
103	            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
104	          }
105	        } catch (e: unknown) {
106	          errorMsg = e instanceof Error ? e.message : String(e);
107	        }
108	      }
109	    } else if (key_name === "RAZORPAY_KEY_ID") {
110	      const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID");
111	      const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
112	      if (!razorpayKeyId || !razorpayKeySecret) {
113	        errorMsg = "RAZORPAY_KEY_ID or RAZORPAY_KEY_SECRET secret is not configured";
114	      } else {
115	        try {
116	          const res = await fetch("https://api.razorpay.com/v1/payments?count=1", {
117	            headers: {
118	              Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
119	            },
120	          });
121	          if (res.ok) {
122	            status = "success";
123	          } else {
124	            const body = await res.text();
125	            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
126	          }
127	        } catch (e: unknown) {
128	          errorMsg = e instanceof Error ? e.message : String(e);
129	        }
130	      }
131	    } else if (key_name === "RESEND_API_KEY") {
132	      // Read API key from platform_config (stored in DB, not env vars)
133	      const { data: config } = await supabase
134	        .from("platform_config")
135	        .select("resend_api_key, email_from_address")
136	        .limit(1)
137	        .single();
138	
139	      const apiKey = config?.resend_api_key;
140	      if (!apiKey) {
141	        errorMsg = "Resend API key is not configured. Add it in Email Settings.";
142	      } else {
143	        try {
144	          // Validate API key by listing domains
145	          const domainsRes = await fetch("https://api.resend.com/domains", {
146	            headers: {
147	              "Authorization": `Bearer ${apiKey}`,
148	              "Content-Type": "application/json",
149	            },
150	          });
151	          const domainsBody = await domainsRes.text();
152	
153	          if (!domainsRes.ok) {
154	            errorMsg = `Invalid API key (${domainsRes.status})`;
155	            details.keyValid = false;
156	          } else {
157	            details.keyValid = true;
158	
159	            try {
160	              const domainsData = JSON.parse(domainsBody);
161	              const domains = domainsData.data || [];
162	              details.totalDomains = domains.length;
163	
164	              // Check if from address domain is verified
165	              const fromEmail = config?.email_from_address || "noreply@rankora.co";
166	              details.fromEmail = fromEmail;
167	              const fromDomain = fromEmail.split("@")[1]?.toLowerCase();
168	
169	              const domainMatch = domains.find((d: any) =>
170	                d.name?.toLowerCase() === fromDomain
171	              );
172	
173	              if (domainMatch) {
174	                details.domainVerified = domainMatch.status === "verified";
175	                details.domainName = domainMatch.name || "";
176	              } else {
177	                details.domainVerified = false;
178	                details.domainName = "";
179	              }
180	            } catch { details.domainVerified = false; }
181	
182	            status = "success";
183	          }
184	        } catch (e: unknown) {
185	          errorMsg = e instanceof Error ? e.message : String(e);
186	        }
187	      }
188	    } else if (key_name === "GEMINI_API_KEY") {
189	      const geminiKey = Deno.env.get("GEMINI_API_KEY");
190	      if (!geminiKey) {
191	        errorMsg = "GEMINI_API_KEY secret is not configured";
192	      } else {
193	        try {
194	          const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${geminiKey}`);
195	          if (res.ok) {
196	            status = "success";
197	            const body = await res.json();
198	            details.modelsCount = body.models?.length || 0;
199	          } else {
200	            const body = await res.text();
201	            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
202	          }
203	        } catch (e: unknown) {
204	          errorMsg = e instanceof Error ? e.message : String(e);
205	        }
206	      }
207	    } else if (key_name === "DODO_PAYMENTS_API_KEY") {
208	      const dodoKey = Deno.env.get("DODO_PAYMENTS_API_KEY");
209	      if (!dodoKey) {
210	        errorMsg = "DODO_PAYMENTS_API_KEY secret is not configured";
211	      } else {
212	        try {
213	          // Read environment from platform_config (UI-editable) or fall back to env var
214	          const { data: cfg } = await supabase
215	            .from("platform_config")
216	            .select("dodo_payments_environment")
217	            .limit(1)
218	            .single();
219	          const dodoEnv = (cfg as any)?.dodo_payments_environment
220	            || Deno.env.get("DODO_PAYMENTS_ENVIRONMENT")
221	            || "test_mode";
222	          const dodoBaseUrl = dodoEnv === "live_mode"
223	            ? "https://live.dodopayments.com"
224	            : "https://test.dodopayments.com";
225	
226	          const res = await fetch(`${dodoBaseUrl}/payments?page_size=1`, {
227	            headers: { Authorization: `Bearer ${dodoKey}` },
228	          });
229	          if (res.ok) {
230	            status = "success";
231	            details.environment = dodoEnv;
232	          } else {
233	            const body = await res.text();
234	            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
235	          }
236	        } catch (e: unknown) {
237	          errorMsg = e instanceof Error ? e.message : String(e);
238	        }
239	      }
240	    } else {
241	      errorMsg = `Unknown integration: ${key_name}`;
242	    }
243	
244	    // Update integrations table
245	    await supabase.from("integrations").update({
246	      last_tested_at: new Date().toISOString(),
247	      last_test_status: status,
248	      is_configured: status === "success",
249	    }).eq("key_name", key_name);
250	
251	    return new Response(JSON.stringify({ status, error: errorMsg || undefined, details }), {
252	      headers: { ...cors, "Content-Type": "application/json" },
253	    });
254	  } catch (err: unknown) {
255	    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
256	      status: 500, headers: { ...cors, "Content-Type": "application/json" },
257	    });
258	  }
259	});
